/**
 * NetPresentValueTab.jsx
 * Net Present Value Calculator
 */

import React, { useState } from 'react';
import { BarChart3 } from 'lucide-react';
import { trackFinancialCalculation } from '../../../hooks/usePageTracking';

const NetPresentValueTab = () => {
  const [initialInvestment, setInitialInvestment] = useState('');
  const [discountRate, setDiscountRate] = useState('');
  const [cashFlows, setCashFlows] = useState(['']);
  const [result, setResult] = useState(null);

  const addCashFlow = () => {
    setCashFlows([...cashFlows, '']);
  };

  const removeCashFlow = (index) => {
    if (cashFlows.length > 1) {
      setCashFlows(cashFlows.filter((_, i) => i !== index));
    }
  };

  const updateCashFlow = (index, value) => {
    const newCashFlows = [...cashFlows];
    newCashFlows[index] = value;
    setCashFlows(newCashFlows);
  };

  const calculateNPV = () => {
    const investment = parseFloat(initialInvestment);
    const rate = parseFloat(discountRate) / 100;

    if (investment && rate && cashFlows.length > 0) {
      let npv = -investment; // Initial investment is negative

      cashFlows.forEach((cf, index) => {
        const cashFlow = parseFloat(cf);
        if (cashFlow) {
          npv += cashFlow / Math.pow((1 + rate), index + 1);
        }
      });

      setResult({
        npv: npv.toFixed(2),
        profitable: npv > 0
      });

      // Track the calculation
      trackFinancialCalculation('net_present_value', {
        initial_investment: investment,
        discount_rate: rate,
        cash_flow_periods: cashFlows.length,
        npv_result: npv,
        is_profitable: npv > 0,
        total_cash_flows: cashFlows.reduce((sum, cf) => sum + (parseFloat(cf) || 0), 0)
      });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 mb-6">
        <BarChart3 className="w-6 h-6 text-red-600" />
        <h2 className="text-2xl font-semibold">Net Present Value Calculator</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Initial Investment ($)</label>
            <input
              type="number"
              value={initialInvestment}
              onChange={(e) => setInitialInvestment(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="100000"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Discount Rate (%)</label>
            <input
              type="number"
              value={discountRate}
              onChange={(e) => setDiscountRate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
              placeholder="10"
              step="0.01"
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Cash Flows by Period ($)</label>
            {cashFlows.map((cf, index) => (
              <div key={index} className="flex gap-2 mb-2">
                <input
                  type="number"
                  value={cf}
                  onChange={(e) => updateCashFlow(index, e.target.value)}
                  className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800"
                  placeholder={`Period ${index + 1}`}
                />
                {cashFlows.length > 1 && (
                  <button
                    onClick={() => removeCashFlow(index)}
                    className="px-3 py-2 bg-red-500 text-white rounded-lg hover:bg-red-600"
                  >
                    ×
                  </button>
                )}
              </div>
            ))}
            <button
              onClick={addCashFlow}
              className="w-full mt-2 px-3 py-2 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg hover:border-red-500 transition-colors"
            >
              + Add Cash Flow
            </button>
          </div>

          <button
            onClick={calculateNPV}
            className="w-full bg-red-600 hover:bg-red-700 text-white py-2 px-4 rounded-lg transition-colors"
          >
            Calculate NPV
          </button>
        </div>

        {result && (
          <div className="bg-gray-50 dark:bg-gray-800 p-6 rounded-lg">
            <h3 className="text-lg font-semibold mb-4">Results</h3>
            <div className="space-y-2">
              <p><span className="font-medium">Net Present Value:</span> ${result.npv}</p>
              <p className={`font-medium ${result.profitable ? 'text-green-600' : 'text-red-600'}`}>
                {result.profitable ? '✓ Profitable Investment' : '✗ Not Profitable'}
              </p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default NetPresentValueTab;
